package org.eclipse.rdf4j.sail.memory;

import static org.assertj.core.api.Assertions.assertThat;
import static org.eclipse.rdf4j.model.util.Values.iri;

import java.util.List;

import org.eclipse.rdf4j.common.iteration.Iterations;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Statement;
import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.Update;
import org.eclipse.rdf4j.query.impl.SimpleDataset;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

class MemorySparqlUpdateDatasetScopeTest {

	private static final IRI G1 = iri("urn:update:g1");
	private static final IRI G2 = iri("urn:update:g2");
	private static final IRI S1 = iri("urn:update:s1");
	private static final IRI S2 = iri("urn:update:s2");
	private static final IRI P = iri("urn:update:source");
	private static final IRI O1 = iri("urn:update:o1");
	private static final IRI O2 = iri("urn:update:o2");

	private SailRepository repository;

	@BeforeEach
	void setUp() {
		repository = new SailRepository(new MemoryStore());
		repository.init();
	}

	@AfterEach
	void tearDown() {
		repository.shutDown();
	}

	@Test
	void omittedUpdateDatasetEnumeratesNamedGraphs() {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			seed(connection);
			IRI copied = iri("urn:update:copied");

			connection.prepareUpdate(QueryLanguage.SPARQL,
					"INSERT { GRAPH ?g { ?s <urn:update:copied> ?o } } "
							+ "WHERE { GRAPH ?g { ?s <urn:update:source> ?o } }")
					.execute();

			List<Statement> copiedStatements = Iterations.asList(connection.getStatements(null, copied, null, false));
			assertThat(copiedStatements).containsExactlyInAnyOrder(
					connection.getValueFactory().createStatement(S1, copied, O1, G1),
					connection.getValueFactory().createStatement(S2, copied, O2, G2));
		}
	}

	@Test
	void bothEmptyUsingAndUsingNamedDatasetsKeepTheirGraphScope() {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			seed(connection);

			String updateText = "INSERT { GRAPH ?g { ?s <urn:update:api-empty> ?o } } "
					+ "WHERE { GRAPH ?g { ?s <urn:update:source> ?o } }";
			Update defaultBehavior = connection.prepareUpdate(QueryLanguage.SPARQL, updateText);
			defaultBehavior.setDataset(new SimpleDataset());
			defaultBehavior.execute();
			IRI copied = iri("urn:update:api-empty");
			assertStatements(connection, copied,
					connection.getValueFactory().createStatement(S1, copied, O1, G1),
					connection.getValueFactory().createStatement(S2, copied, O2, G2));

			connection.prepareUpdate(QueryLanguage.SPARQL,
					"INSERT { GRAPH ?g { ?s <urn:update:using-named> ?o } } "
							+ "USING NAMED <urn:update:g1> "
							+ "WHERE { GRAPH ?g { ?s <urn:update:source> ?o } }")
					.execute();
			IRI usingNamed = iri("urn:update:using-named");
			assertStatements(connection, usingNamed,
					connection.getValueFactory().createStatement(S1, usingNamed, O1, G1));

			connection.prepareUpdate(QueryLanguage.SPARQL,
					"INSERT { GRAPH ?g { ?s <urn:update:using-default> ?o } } "
							+ "USING <urn:update:g1> "
							+ "WHERE { GRAPH ?g { ?s <urn:update:source> ?o } }")
					.execute();
			assertStatements(connection, iri("urn:update:using-default"));
		}
	}

	@Test
	void bothEmptyReadSetsDoNotDiscardExplicitMutationTargets() {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			seed(connection);
			IRI target = iri("urn:update:mutation-target");
			IRI copied = iri("urn:update:metadata-copy");
			SimpleDataset dataset = new SimpleDataset();
			dataset.setDefaultInsertGraph(target);
			Update update = connection.prepareUpdate("INSERT { ?s <" + copied + "> ?o } "
					+ "WHERE { GRAPH ?g { ?s <urn:update:source> ?o } }");
			update.setDataset(dataset);
			update.execute();
			assertStatements(connection, copied,
					connection.getValueFactory().createStatement(S1, copied, O1, target),
					connection.getValueFactory().createStatement(S2, copied, O2, target));
		}
	}

	@Test
	void withAndUsingDetermineTheWhereGraphAndInsertGraph() {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			seed(connection);

			connection.prepareUpdate(QueryLanguage.SPARQL,
					"WITH <urn:update:g1> INSERT { ?s <urn:update:with> ?o } "
							+ "WHERE { ?s <urn:update:source> ?o }")
					.execute();
			IRI with = iri("urn:update:with");
			assertStatements(connection, with, connection.getValueFactory().createStatement(S1, with, O1, G1));

			connection.prepareUpdate(QueryLanguage.SPARQL,
					"WITH <urn:update:g1> INSERT { ?s <urn:update:with-using> ?o } "
							+ "USING <urn:update:g2> WHERE { ?s <urn:update:source> ?o }")
					.execute();
			IRI withUsing = iri("urn:update:with-using");
			assertStatements(connection, withUsing,
					connection.getValueFactory().createStatement(S2, withUsing, O2, G1));
		}
	}

	private static void assertStatements(SailRepositoryConnection connection, IRI predicate, Statement... expected) {
		List<Statement> statements = Iterations.asList(connection.getStatements(null, predicate, null, false));
		assertThat(statements).containsExactlyInAnyOrder(expected);
	}

	private static void seed(SailRepositoryConnection connection) {
		connection.add(S1, P, O1, G1);
		connection.add(S2, P, O2, G2);
		connection.add(iri("urn:update:default-subject"), P, iri("urn:update:default-object"));
	}
}
